theorem coreBochnerPairing_eq_setIntegral
    {μ : MeasureTheory.Measure X} {D : Set V}
    {T : V →ₗ[ℂ] (X → ℂ)} {F : StrongDual ℂ V} {ρ : X → ℂ}
    (hpair : CoreBochnerPairing μ D T F ρ) {v : V} (hvD : v ∈ D)
    {s : Set X} (hs : tsupport (T v) ⊆ s) :
    dualPairing F v = ∫ x in s, linearTestIntegrand ρ T v x ∂μ:=

theorem coreAntiBochnerPairing_eq_setIntegral
    {μ : MeasureTheory.Measure X} {D : Set V}
    {T : V →ₗ[ℂ] (X → ℂ)} {F : StrongAntiDual V} {ρ : X → ℂ}
    (hpair : CoreAntiBochnerPairing μ D T F ρ) {v : V} (hvD : v ∈ D)
    {s : Set X} (hs : tsupport (T v) ⊆ s) :
    antiDualPairing F v = ∫ x in s, antiTestIntegrand ρ T v x ∂μ:=

theorem solvesWeakWithPotential_on_truncatedTestCore
    {A potentialOp : WeakOperator V} {u : V} {f : StrongDual ℂ V}
    {μ : MeasureTheory.Measure X} {D : Set V}
    {T : V →ₗ[ℂ] (X → ℂ)} {ρA ρP : X → ℂ}
    {FY : ι → Set X} {i : ι} {v : V}
    (hEq : SolvesWeakWithPotential A potentialOp u f)
    (hregA : CoreBochnerRegular μ D T ρA)
    (hregP : CoreBochnerRegular μ D T ρP)
    (hpairA : CoreBochnerPairing μ D T (A u) ρA)
    (hpairP : CoreBochnerPairing μ D T (potentialOp u) ρP)
    (hv : v ∈ truncatedTestCore D T FY i) :
    dualPairing f v =
      ∫ x in FY i, linearTestIntegrand (ρA + ρP) T v x ∂μ:=

theorem solvesWeakAntiWithPotential_on_truncatedTestCore
    {A potentialOp : WeakAntiOperator V} {u : V} {f : StrongAntiDual V}
