    (hpairP : CoreAntiBochnerPairing μ D T (potentialOp u) ρP)
    (hv : v ∈ truncatedTestCore D T FY i) :
    antiDualPairing f v =
      ∫ x in FY i, antiTestIntegrand (ρA + ρP) T v x ∂μ:=

